(() => {
  'use strict';
  const ROOT='/assets/ui/territory-war/formation-v1/',WORLD='/assets/ui/territory-war/network-v2/';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt=v=>Math.max(0,Number(v)||0).toLocaleString('ko-KR');
  const sideName=(s,side)=>String(s.settings?.[side==='A'?'teamAName':'teamBName']||side+' 진영');
  const assigned=mine=>['A','B'].includes(mine?.side);
  const parsed=value=>{try{return typeof value==='string'?JSON.parse(value):value||{}}catch{return {}}};
  const isNetwork=s=>Boolean(s.network)||Number(s.round?.warfare_version)===6||s.allocation==='INDIVIDUAL';
  function button(label,attribute,kind='secondary',disabled=false){return `<button type="button" class="tf-button tf-button--${kind}" ${attribute}${disabled?' disabled':''}><span>${esc(label)}</span></button>`}
  function header(title){return `<header class="tf-header"><div class="tf-brand"><img src="/assets/ui/brand/reverse-call-20261016/icon-192.png" alt="리버스콜 REVERSE CALL" width="82" height="82"><div><small>영토전</small><h1>${esc(title)}</h1></div></div><div class="tf-header-controls">${button('↻','data-tw3-refresh aria-label="영토전 새로고침"','square')}${button('×','data-tw3-close aria-label="영토전 닫기"','square')}</div></header>`}
  function phases(status){const items=[['RECRUITING','모집신청'],['PREPARING','진영 편성'],['ACTIVE','전선 공성'],['FINISHED','정산·수령']],current=items.findIndex(([key])=>key===status);return `<ol class="tf-phases" aria-label="영토전 진행 단계">${items.map(([key,label],index)=>`<li class="${index===current?'is-current':index<current?'is-complete':''}" ${key===status?'aria-current="step"':''}><span>0${index+1}</span><b>${label}</b></li>`).join('')}</ol>`}
  function force(s){const mine=s.mine,breakdown=parsed(mine?.formation_breakdown_json),ids=parsed(mine?.deck_snapshot),known=Array.isArray(ids),count=known?Math.min(5,ids.length):breakdown.deckComplete===true?5:0,complete=breakdown.deckComplete===true;return {mine,complete,count}}
  function readiness(s){
    const {mine,complete,count}=force(s),loadout=parsed(mine?.loadout_bonus_json),cards=Array.isArray(loadout.territoryCards)?loadout.territoryCards:[],mercenary=loadout.mercenary;
    return `<div class="tf-readiness"><div><small>전투 준비</small><b>${!mine?'참가 신청 전':complete?'출전 덱 준비 완료':'PVP 덱 확인 필요'}</b><span>${mine?'교전 시작 전 현재 PVP 편성을 자동 반영합니다.':'저장된 PVP 덱을 바탕으로 참가합니다.'}</span></div><strong>${mine?count:'—'}<small>/ 5</small></strong></div><div class="tf-live-cards" aria-label="현재 출전 카드">${Array.from({length:5},(_,i)=>{const card=cards[i];return `<div class="tf-live-card">${card?.image?`<img src="${esc(card.image)}" alt="${esc(card.name)}" loading="lazy">`:`<span class="tf-live-placeholder">0${i+1}</span>`}<small>${esc(card?.rarity||'CARD')}</small><b>${esc(card?.name||'편성 확인')}</b></div>`}).join('')}</div>${mine?`<div class="tf-live-mercenary"><span>함께 출전하는 용병</span><strong>${esc(mercenary?.name||mercenary?.code||'PVP 용병 미편성')}</strong><small>${mercenary?'PVP 용병 편성 적용':'용병 관리에서 PVP 편성을 선택하세요.'}</small></div>`:''}`;
  }
  function factions(s,preparing){const mine=s.mine,network=isNetwork(s);return `<section class="tf-factions" aria-label="영토전 진영"><div class="tf-section-heading"><div><small>출전 진영</small><h2>두 진영, 하나의 전선</h2></div><span>${network?'개인 균형 편성':'진영 배정'}</span></div><div class="tf-faction-grid">${['A','B'].map(side=>`<article class="tf-faction side-${side.toLowerCase()} ${mine?.side===side?'is-mine':''}"><img src="${WORLD}${side==='A'?'guardian':'purifier'}-citadel.webp" alt="" width="180" height="180"><div><small>${side==='A'?'서부 진영':'동부 진영'}</small><h3>${esc(sideName(s,side))}</h3><p>${preparing?`${fmt(s.counts?.[side])}명의 전투단`:'모집 종료 후 진영이 결정됩니다.'}</p><span>${mine?.side===side?'내 소속 진영':preparing?'진영 배정 완료':network?'인원 · 전력 · 최근 참여 이력 반영':'이번 회차의 편성 규칙 적용'}</span></div></article>`).join('')}</div></section>`}
  function squad(s,{teamHtml='',canRefresh=false,embedded=false}={}){const mine=s.mine,{complete}=force(s),rank=Number(mine?.contribution_rank||0),total=Number(mine?.contribution_total||0);return `<section class="tf-squad ${embedded?'tf-squad--embedded':''}" aria-label="내 전투단" id="twFormationSquad"><div class="tf-section-heading"><div><small>등록 전력</small><h2>내 전투단</h2></div><span>${mine?'등록 전력':'미참가'}</span></div><div class="tf-squad-hero">${teamHtml||`<div class="tf-team-name"><small>소속 진영</small><strong>${assigned(mine)?esc(sideName(s,mine.side)):mine?'배정 대기':'미참가'}</strong><p>${assigned(mine)?'이번 회차에 배정된 내 진영입니다.':'모집 종료 후 진영을 확인할 수 있습니다.'}</p></div>`}<img class="tf-squad-citadel" src="${WORLD}${mine?.side==='B'?'purifier':'guardian'}-citadel.webp" alt="" width="180" height="180"></div><div class="tf-power"><span>등록 덱 전투력</span><strong>${mine?fmt(mine.deck_power):'—'}</strong><small>${mine?'전장에 적용된 등록 전력입니다.':'참가 신청 후 전력을 확인할 수 있습니다.'}</small></div>${readiness(s)}<dl class="tf-squad-stats"><div><dt>행동력</dt><dd>${fmt(mine?.energy)}<small> / ${fmt(s.settings?.energyMax)}</small></dd></div><div><dt>누적 공격</dt><dd>${fmt(mine?.attacks)}<small>회</small></dd></div><div><dt>현재 기여도</dt><dd>${rank?`${fmt(rank)}위${total?`<em>/ ${fmt(total)}명</em>`:''}`:'집계 대기'}</dd></div></dl><div class="tf-squad-footer"><p>${!mine?'참가 신청 후 내 전투단 정보를 확인할 수 있습니다.':canRefresh?'PVP 카드·용병·펫·장비 변경은 다음 교전부터 적용됩니다. 지금 최신화해 편성을 확인할 수도 있습니다.':complete?'교전 시작 시 현재 편성을 사용하며 진행 중인 교전 결과는 유지됩니다.':'PVP 덱 5장을 저장한 뒤 전투 준비를 최신화하세요.'}</p>${button(canRefresh?'전투 준비 최신화':mine?'최신화 대기':'참가 후 이용 가능','data-tw3-loadout-refresh','primary',!canRefresh)}</div></section>`}
  function lobby(s,{rewardHtml='',canRefresh=false}={}){
    const status=s.round?.status,preparing=status==='PREPARING',off=s.mode==='OFF'||!s.round||status==='DISABLED',mine=s.mine,network=isNetwork(s),mandatory=Number(mine?.mandatory_clan)===1;
    const title=off?'다음 전장을 준비합니다':preparing?'진영 편성 완료':'이번 전선에 합류하세요';
    const name=String(s.round?.battle_name||`제${fmt(s.round?.id)}회 영토전`),deadline=preparing?s.round?.starts_at:s.round?.recruitment_ends_at;
    const count=Number(s.counts?.total||0),min=Math.max(1,Number(s.settings?.minParticipants||6));
    const action=off?button('전장 소식 새로고침','data-tw3-refresh','secondary'):preparing?button('개전 준비 확인','data-twf-squad','primary'):mine?button('PVP 덱 최신화','data-tw3-loadout-refresh','primary',!canRefresh)+(s.registration?.canCancel&&!mandatory?button('참가 신청 취소','data-tw3-unregister','danger'):''):button('영토전 참가 신청','data-tw3-register','primary',!s.registration?.canRegister);
    return `<section class="tf-shell" data-twf-status="${off?'OFF':esc(status)}">${header(off?'운영 대기':preparing?'진영 편성':'모집신청')}<main class="tf-main">${phases(off?'OFF':status)}<section class="tf-hero"><div class="tf-hero-copy"><span class="tf-kicker">${off?'영토전 운영 대기':preparing?'개전 준비':'참가자 모집 중'}</span><h2>${title}</h2><p>${off?'새로운 전선, 다시 쓰일 승리의 기록.<br>운영이 시작되면 이곳에서 참가할 수 있습니다.':preparing?`${assigned(mine)?esc(sideName(s,mine.side))+' 진영으로 출전합니다.':'양 진영의 전투 준비가 진행 중입니다.'}<br>개전까지 내 전투단과 등록 전력을 확인하세요.`:network?'아홉 개의 거점, 세 갈래의 전선.<br>당신의 전투단으로 승리의 경로를 여세요.':'당신의 전투단으로 새로운 전선에 합류하세요.<br>모집 종료 후 소속 진영이 결정됩니다.'}</p><div class="tf-hero-caption"><span>${network||off?'09':'02'}<small>${network||off?'거점':'진영'}</small></span><span>${network||off?'03':'01'}<small>${network||off?'진격로':'전선'}</small></span><span>02<small>진영</small></span></div></div><aside class="tf-entry"><div class="tf-entry-top"><span>${off?'운영 대기':esc(name)}</span><i>${off?'대기':preparing?'편성 완료':'모집 중'}</i></div><small>${off?'다음 영토전':preparing?'내 소속 진영':'내 참가 상태'}</small><h3>${off?'다음 전선을 준비하세요':preparing?assigned(mine)?esc(sideName(s,mine.side)):'참가 정보 확인':mandatory?'자동 참가 완료':mine?'참가 신청 완료':'참가 신청 대기'}</h3><p>${off?'현재 영토전 운영이 중지되어 있습니다.':preparing?'진영 편성이 완료되었습니다. 개전 시 전장이 열립니다.':mandatory?'클랜 로스터 자동 참가입니다. 신청 취소는 제공하지 않습니다.':mine?'등록한 전투단으로 출전합니다. 모집 종료 전 신청을 취소할 수 있습니다.':s.registration?.canRegister?'PVP 덱 5장을 저장하고 전선에 합류하세요.':'현재 참가 신청을 진행할 수 없습니다.'}</p>${off?`<div class="tf-off-seal"><span>✧</span><b>전장 개막 대기</b></div>`:`<div class="tf-countdown"><span>${preparing?'개전까지':'모집 종료까지'}</span><time data-tw3-countdown="${esc(deadline||'')}">—</time></div><div class="tf-roster-count"><span>${preparing?'전체 전투단':'집결한 전투단'}</span><b>${fmt(count)}<small>명</small></b></div>${!preparing?`<meter min="0" max="${min}" value="${Math.min(count,min)}" aria-label="최소 참가 인원 충족"></meter><span class="tf-minimum">${count>=min?'전투 개시 인원 충족':`최소 ${fmt(min)}명 모집`}</span>`:''}`}${mine&&!off&&!preparing?`<div class="tf-entry-power"><span>등록 전투력</span><b>${fmt(mine.deck_power)}</b></div>`:''}<div class="tf-entry-actions">${action}</div></aside></section>${!off?factions(s,preparing):''}${preparing?squad(s,{canRefresh,embedded:true}):!off?`<section class="tf-ruleline"><span>01 <b>PVP 덱 5장 준비</b></span><span>02 <b>${network?'개인 균형 편성':'진영 배정'}</b></span><span>03 <b>${network?'연결 거점부터 진격':'상대 진영 공략'}</b></span></section><p class="tf-policy">${network?'인원·전투력·최근 5회 참여 이력으로 양 진영을 편성합니다. 같은 클랜도 서로 다른 진영에 배정될 수 있습니다.':'현재 회차의 참가·진영 배정 규칙을 따릅니다.'}</p>`:''}${rewardHtml?`<div class="tf-reward-wrap">${rewardHtml}</div>`:''}<footer class="tf-footer"><span>리버스콜 · 영토전</span><span>${off?'개막 전까지 편안히 준비하세요.':preparing?'전투단을 점검하고 개전을 기다리세요.':'작은 선택이 전황을 바꿉니다.'}</span></footer></main></section>`;
  }
  globalThis.CNineTerritoryFormation=Object.freeze({lobby,squad,force});
})();
